import { useState, useEffect } from "react";
import api from "../api";

function MealPlanPage() {
  const [families, setFamilies] = useState([]);
  const [selectedFamily, setSelectedFamily] = useState(null);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedMeals, setSelectedMeals] = useState(["Breakfast", "Lunch", "Dinner"]);
  const [plans, setPlans] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const MEAL_TYPES = ["Breakfast", "Lunch", "Dinner", "Snacks"];

  useEffect(() => {
    loadFamilies();
  }, []);

  const loadFamilies = async () => {
    try {
      const res = await api.get("/families/");
      setFamilies(res.data);
      if (res.data && res.data.length > 0) {
        setSelectedFamily(res.data[0].id);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const toggleMeal = (meal) => {
    setSelectedMeals(prev => 
      prev.includes(meal) ? prev.filter(m => m !== meal) : [...prev, meal]
    );
  };

  const generateAndLoadPlan = async () => {
    if (!selectedFamily) return;
    if (selectedMeals.length === 0) {
      setError("Please select at least one meal to generate.");
      return;
    }
    
    setLoading(true);
    setError("");
    try {
      const res = await api.post(`/families/${selectedFamily}/daily-plan`, {
        date,
        meals: selectedMeals
      });
      setPlans(res.data);
    } catch (err) {
      console.error(err);
      setError("Failed to load or generate plan. Please try again.");
    }
    setLoading(false);
  };

  return (
    <div className="page anim-fade-in">
      <h1 style={{ color: "#38bdf8", textShadow: "0 0 10px rgba(56,189,248,0.3)" }}>
        Daily Meal Plan Generator
      </h1>
      
      <div className="card" style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div style={{ display: 'flex', gap: '20px', alignItems: 'center', flexWrap: 'wrap' }}>
          {families.length > 0 && (
            <select 
              value={selectedFamily || ""} 
              onChange={e => setSelectedFamily(e.target.value)}
              className="date-picker"
              style={{ padding: "12px", borderRadius: "8px" }}
            >
              {families.map(f => (
                <option key={f.id} value={f.id}>{f.name}</option>
              ))}
            </select>
          )}

          <input 
            type="date" 
            className="date-picker"
            value={date}
            onChange={(e) => setDate(e.target.value)}
          />
        </div>

        <div>
          <h3 style={{ margin: "10px 0", color: "#94a3b8" }}>Select Required Meals:</h3>
          <div className="meal-bar-container">
            {MEAL_TYPES.map(meal => (
              <button 
                key={meal}
                className={`meal-btn ${selectedMeals.includes(meal) ? 'active' : ''}`}
                onClick={() => toggleMeal(meal)}
              >
                {meal}
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={generateAndLoadPlan} 
          disabled={loading}
          style={{ 
            alignSelf: 'flex-start', 
            background: loading ? "#475569" : "#0ea5e9",
            fontWeight: "bold",
            padding: "12px 24px"
          }}
        >
          {loading ? "Generating..." : "Generate & View Meals"}
        </button>
      </div>

      {error && <p style={{ color: "#ef4444" }}>{error}</p>}

      {plans.length > 0 && !loading && (
        <div className="grid">
          {plans.map((plan, idx) => (
            <div 
              key={idx} 
              className="card daily-plan-card anim-fade-in" 
              style={{ animationDelay: `${idx * 0.15}s` }}
            >
              <h2 className="meal-type-title">{plan.meal_type}</h2>
              <div className="pre">{plan.plan_text}</div>
            </div>
          ))}
        </div>
      )}

      {plans.length === 0 && !loading && !error && (
        <div style={{ textAlign: "center", marginTop: "40px", color: "#64748b" }}>
          <h3>No meals generated for this date yet.</h3>
          <p>Select your desired meals and hit generate!</p>
        </div>
      )}
    </div>
  );
}

export default MealPlanPage;
